//! SEC rebuild (CONTRACT-sec-rebuild.md N1 to N3): the SEC relay as `deploy/prod/feeds/sec.py` emits it, published with the
//! public test rule on (`publish_stored_checked`, the call the binary makes on datumesh-http) on a mesh-test-like config, so
//! every descriptor goes through core's checks (spec 7.1 and spec-0.6.2: a number declares its unit) and every cell through
//! the store's. Needs the unreleased core 0.3.11 and formula 0.5.2 (`public:` licences, `shares`, `pure`).
//!
//! The files are generated by `fixtures/make_sec_stub.py` from `sec.emit` (never by hand):
//!
//! * `sec_views_stub_relay.jsonl`: the saved companyfacts of Caterpillar and JPMorgan Chase and a synthetic restated company,
//!   with the source-conformance tests of the saved Assets frame (the relay the views read);
//! * `sec_relay_forms.jsonl`: one synthetic company holding every kind of unit: money in three currencies, shares, per share
//!   in two currencies and a pure number, all through the one `company_fact`.
//!
//! Checked: both are accepted (two stored functions, `company_fact` and `sec/annual_report`, and one class, the filing class
//! with its six stored methods) and a second run changes nothing; the live mesh answers every cell with the figure as filed,
//! relayed with the source and the `public:` licence (the filing class too), and `sec/annual_report` as primary, with no
//! source, under the same licence; the descriptors that fail core's checks are refused with `E_CANON_UNIT`.

mod common;

use std::path::PathBuf;
use std::sync::Arc;

use common::lite::{Lite, HOST, NOW};
use common::pub031::{opts, write};
use common::{key_doc, key_for, Node, Setup, TestDb, BIND_TX};
use datumesh_http::publish::publish_stored_checked;
use datumesh_store::Store;
use serde_json::{json, Value};

const PUBLIC: &str = "public:https://www.sec.gov/about/privacy-information";
const METHODS: [&str; 6] = ["cik", "form", "filed", "fiscal_year", "fiscal_period", "period_end"];

fn feeds() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("deploy/prod/feeds")
}

fn lines(name: &str) -> Vec<String> {
    let p = feeds().join("fixtures").join(name);
    std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display())).lines().map(str::to_string).collect()
}

fn json_of(l: &str) -> Value {
    serde_json::from_str(l).unwrap()
}

fn relay(name: &str) -> String {
    format!("{HOST}/relay/sec.gov/{name}")
}

fn annual() -> String {
    format!("{HOST}/sec/annual_report")
}

fn count(ls: &[String], key: &str) -> usize {
    ls.iter().filter(|l| json_of(l).get(key).is_some()).count()
}

fn publish(lite: &Lite, ls: &[String]) -> Result<datumesh_http::publish::Published, datumesh_http::publish::PublishError> {
    let f = write(lite, "relay.jsonl", ls);
    publish_stored_checked(&*lite.store, &lite.key, HOST, &[HOST.to_string()], &f, &opts(NOW))
}

#[test]
fn the_stub_relay_publishes_under_the_public_rule_and_a_second_run_changes_nothing() {
    let ls = lines("sec_views_stub_relay.jsonl");
    let lite = Lite::new("sr-stub");
    let p = publish(&lite, &ls).unwrap_or_else(|e| panic!("{e}"));
    assert_eq!(p.functions, 2, "company_fact and sec/annual_report: {p:?}");
    assert_eq!(p.classes, 1, "the filing class, with its six methods: {p:?}");
    assert_eq!(p.cells as usize, count(&ls, "cell"), "{p:?}");
    assert!(p.cells > 800, "{p:?}");
    let again = publish(&lite, &ls).unwrap_or_else(|e| panic!("{e}"));
    assert_eq!((again.functions, again.classes, again.versions), (0, 0, 0), "{again:?}");
}

#[test]
fn every_kind_of_unit_publishes_through_the_one_function() {
    let ls = lines("sec_relay_forms.jsonl");
    let lite = Lite::new("sr-forms");
    let p = publish(&lite, &ls).unwrap_or_else(|e| panic!("{e}"));
    assert_eq!((p.functions, p.classes), (2, 1), "company_fact, annual_report; the filing class: {p:?}");
    assert_eq!(p.cells as usize, count(&ls, "cell"), "{p:?}");
    let fns: Vec<String> = ls.iter().filter_map(|l| json_of(l).get("function").map(|f| f.as_str().unwrap().to_string())).collect();
    assert_eq!(fns, vec![relay("company_fact"), annual()], "one relay function: no per-unit split, no filing(accession, field)");
    assert!(lite.bound_tx(&relay("company_fact")).is_some() && lite.bound_tx(&annual()).is_some());
    for m in METHODS {
        assert!(lite.bound_tx(&relay(&format!("filing/{m}"))).is_some(), "filing/{m} unbound");
    }
    for gone in ["company_fact_shares", "company_fact_per_share", "company_fact_ratio", "filing", "filing_for"] {
        assert!(!fns.contains(&relay(gone)), "{gone}");
    }
    // the cells of the three left-out units (Liabilities in CAD/EUR, Revenues in acre, NetIncomeLoss in USD-per-gal)
    // are not in the file: seven cells are, one for each filed unit that units.md can say
    let facts: Vec<Value> = ls.iter().map(|l| json_of(l)).filter(|v| v.pointer("/cell/fn") == Some(&json!(relay("company_fact")))).collect();
    assert_eq!(facts.len(), 7);
    let mut units: Vec<&str> = facts.iter().map(|v| v.pointer("/cell/args/unit/value").unwrap().as_str().unwrap()).collect();
    units.sort();
    assert_eq!(units, ["EUR", "EUR/shares", "USD", "USD/shares", "USN", "pure", "shares"]);
    assert!(facts.iter().all(|v| v["licence"] == PUBLIC && v["source"]["name"] == "sec.gov"));
    // the filing class's methods carry the source and the same licence
    let filing_cells: Vec<Value> =
        ls.iter().map(|l| json_of(l)).filter(|v| v.pointer("/cell/fn").is_some_and(|f| f.as_str().unwrap().contains("/filing/"))).collect();
    assert_eq!(filing_cells.len(), 6);
    assert!(filing_cells.iter().all(|v| v["licence"] == PUBLIC && v["source"]["name"] == "sec.gov"));
    // sec/annual_report: stored, signed by the operator, no source
    let ann: Vec<Value> = ls.iter().map(|l| json_of(l)).filter(|v| v.pointer("/cell/fn") == Some(&json!(annual()))).collect();
    assert_eq!(ann.len(), 1);
    assert!(ann[0].get("source").is_none() && ann[0]["licence"] == PUBLIC, "{}", ann[0]);
}

fn signature_of(ls: &[String], name: &str) -> Value {
    ls.iter().map(|l| json_of(l)).find(|v| v["function"] == name).unwrap()["signature"].clone()
}

#[test]
fn the_descriptors_are_the_ones_the_rebuild_names() {
    let ls = lines("sec_relay_forms.jsonl");
    let cf = signature_of(&ls, &relay("company_fact"));
    assert_eq!(cf["returns"], json!({"type": "number", "unit": {"arg": "unit"}}));
    assert_eq!(cf["order"], json!(["cik", "concept", "unit", "accession", "period_start", "period_end"]));
    assert_eq!(cf["args"]["period_start"], json!({"type": "date", "valid": false}));
    assert_eq!(cf["args"]["period_end"], json!({"type": "date", "valid": false}));
    assert_eq!(cf["args"]["accession"], json!({"type": "string", "valid": false}));
    assert!(cf["args"].get("taxonomy").is_none() && cf["args"].get("period").is_none());
    let ar = signature_of(&ls, &annual());
    assert_eq!(ar["returns"], json!("string"));
    assert_eq!(ar["order"], json!(["cik", "fiscal_year"]));
    assert_eq!(ar["args"]["fiscal_year"], json!({"type": "number", "unit": "1", "valid": false}));
    // the six stored methods of the filing class, in the contract's order, each keyed by accession
    let ds: Vec<Value> =
        ls.iter().map(|l| json_of(l)).filter(|v| v.get("descriptor").is_some() && v.get("class").is_none()).map(|v| v["descriptor"].clone()).collect();
    assert_eq!(ds.len(), 6);
    let returns = [json!("string"), json!("string"), json!("date"), json!({"type": "number", "unit": "1"}), json!("string"), json!("date")];
    for (d, r) in ds.iter().zip(returns) {
        assert_eq!(d["code"], json!({"body": "", "lang": "stored"}));
        assert_eq!(d["signature"]["order"], json!(["accession"]));
        assert_eq!(d["signature"]["returns"], r);
    }
    let class: Vec<Value> = ls.iter().map(|l| json_of(l)).filter(|v| v.get("class").is_some()).collect();
    assert_eq!(class.len(), 1);
    assert_eq!(class[0]["class"], relay("filing").as_str());
    assert_eq!(class[0]["descriptor"]["order"], json!(["accession"]));
    assert_eq!(class[0]["descriptor"]["steward"]["namespace"], format!("{HOST}/relay/sec.gov").as_str());
    // the catalogue: accession is an open key of the relay function, the class and each method (H7 of CONTRACT-0.4.9)
    for name in [relay("company_fact"), relay("filing")].into_iter().chain(METHODS.iter().map(|m| relay(&format!("filing/{m}")))) {
        let c = ls.iter().map(|l| json_of(l)).find(|v| v["catalog"] == name.as_str()).unwrap_or_else(|| panic!("{name}"));
        assert_eq!(c["open_keys"], json!(["accession"]), "{name}");
    }
    let a = ls.iter().map(|l| json_of(l)).find(|v| v["catalog"] == annual().as_str()).unwrap();
    assert!(a.get("open_keys").is_none());
}

/// The refusals the real load showed, kept as tests: the fetcher's earlier descriptors cannot come back. `change` edits a
/// function line or a descriptor line.
fn refused_with(label: &str, change: impl Fn(&mut Value), want: &[&str]) {
    let mut ls = lines("sec_relay_forms.jsonl");
    for l in ls.iter_mut() {
        let mut v = json_of(l);
        if v.get("function").is_some() || (v.get("descriptor").is_some() && v.get("class").is_none()) {
            change(&mut v);
            *l = v.to_string();
        }
    }
    let lite = Lite::new(label);
    let e = publish(&lite, &ls).expect_err("refused");
    for w in want {
        assert!(e.detail.contains(w) || e.to_string().contains(w), "{label}: {w} not in {e} / {}", e.detail);
    }
}

#[test]
fn a_number_return_without_a_unit_is_refused_as_it_was_on_mesh_test() {
    refused_with(
        "sr-nounit",
        |v| {
            if v["function"] == relay("company_fact").as_str() {
                v["signature"]["returns"] = json!({"type": "number"});
            }
        },
        &["E_CANON_UNIT", "$.signature.returns"],
    );
    // a method of the filing class that returns a number must declare its unit too
    refused_with(
        "sr-fy-nounit",
        |v| {
            if v.get("descriptor").is_some() && v["descriptor"]["signature"]["returns"] == json!({"type": "number", "unit": "1"}) {
                v["descriptor"]["signature"]["returns"] = json!({"type": "number"});
            }
        },
        &["E_CANON_UNIT"],
    );
}

#[test]
fn a_string_return_written_as_an_object_and_a_string_fiscal_year_are_not_what_the_fetcher_emits() {
    refused_with(
        "sr-strobj",
        |v| {
            if v["function"] == annual().as_str() {
                v["signature"]["returns"] = json!({"type": "string"});
            }
        },
        &["E_CANON_UNIT"],
    );
    // `unit` on a string argument is E_CANON_UNIT too
    refused_with(
        "sr-strunit",
        |v| {
            if v["function"] == annual().as_str() {
                v["signature"]["args"]["cik"] = json!({"type": "string", "unit": "1", "valid": false});
            }
        },
        &["E_CANON_UNIT"],
    );
}

#[test]
fn a_public_licence_without_an_https_url_is_refused() {
    let mut ls = lines("sec_relay_forms.jsonl");
    let mut done = false;
    for l in ls.iter_mut() {
        let mut v = json_of(l);
        if !done && v.pointer("/cell/fn") == Some(&json!(relay("company_fact"))) {
            v["licence"] = json!("public:http://www.sec.gov/about/privacy-information");
            *l = v.to_string();
            done = true;
        }
    }
    assert!(done);
    assert!(publish(&Lite::new("sr-badpublic"), &ls).is_err());
}

fn path_of(call: &str) -> String {
    let (name, rest) = call.split_once('(').unwrap();
    let args = rest.strip_suffix(')').unwrap();
    let mut q: Vec<String> = args
        .split(", ")
        .map(|a| {
            let (k, v) = a.split_once(": ").unwrap();
            format!("{k}={}", v.trim_matches('"').replace('/', "%2F"))
        })
        .collect();
    q.sort();
    format!("/cell/{name}?{}", q.join("&"))
}

/// `name(k: v, ...)` of a cell line, strings quoted, dates and numbers bare.
fn call_of(cell: &Value) -> String {
    let fnname = cell["cell"]["fn"].as_str().unwrap();
    let args: Vec<String> = cell["cell"]["args"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(k, a)| {
            let v = a["value"].as_str().unwrap();
            if a["type"] == "string" {
                format!("{k}: \"{v}\"")
            } else {
                format!("{k}: {v}")
            }
        })
        .collect();
    format!("{fnname}({})", args.join(", "))
}

/// The live mesh answers every cell of the forms file with the figure as filed: relayed, with the source and the public
/// licence; the filing class's methods the same; sec/annual_report as primary, with no source.
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn the_live_mesh_answers_every_kind_of_cell() {
    let db = Arc::new(TestDb::migrated());
    let key = key_for(HOST);
    let store = Arc::new(common::bl(|| db.store(8)));
    common::bl(|| store.put_namespace(HOST, &key_doc(HOST, &key), BIND_TX).unwrap());
    let dir = common::out_dir().join(format!("sec-relay-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let ls = lines("sec_relay_forms.jsonl");
    let p = dir.join("forms.jsonl");
    std::fs::write(&p, ls.iter().map(|l| format!("{l}\n")).collect::<String>()).unwrap();
    common::bl(|| publish_stored_checked(&*store, &key, HOST, &[HOST.to_string()], &p, &opts(NOW))).unwrap_or_else(|e| panic!("{e}"));
    let node = Node::start_with(Setup { db: Some(db.clone()), ..Setup::new(HOST) }, |_| {}, |b| b).await;

    let (mut facts, mut filings, mut reports) = (0, 0, 0);
    for l in &ls {
        let v = json_of(l);
        let Some(f) = v.pointer("/cell/fn").and_then(Value::as_str) else { continue };
        let call = call_of(&v);
        let r = node.get(&path_of(&call)).await;
        let a: Value = serde_json::from_slice(&r.body).unwrap_or_else(|x| panic!("{call}: {x}: {}", r.text()));
        assert_eq!(a["outcome"], "ok", "{call}: {a}");
        assert_eq!(a["receipt"]["value"], v["value"]["value"], "{call}: {a}");
        assert_eq!(a["receipt"]["licence"], PUBLIC, "{call}: {a}");
        if f == annual() {
            assert_eq!(a["trust"], "primary", "{call}: {a}");
            assert!(a["receipt"].get("source").map_or(true, Value::is_null), "no source: {call}: {a}");
            reports += 1;
        } else {
            assert_eq!(a["trust"], "relayed", "{call}: {a}");
            assert_eq!(a["receipt"]["source"]["name"], "sec.gov", "{call}: {a}");
            if f == relay("company_fact") {
                facts += 1;
            } else {
                filings += 1;
            }
        }
    }
    assert_eq!((facts, filings, reports), (7, 6, 1));
    // the catalogue's examples answer too
    let mut seen = 0;
    for l in &ls {
        let v = json_of(l);
        if v.get("catalog").is_none() {
            continue;
        }
        for e in v["examples"].as_array().unwrap() {
            let call = e["call"].as_str().unwrap();
            let r = node.get(&path_of(call)).await;
            let a: Value = serde_json::from_slice(&r.body).unwrap_or_else(|x| panic!("{call}: {x}: {}", r.text()));
            assert_eq!(a["outcome"], "ok", "{call}: {a}");
            assert_eq!(a["receipt"]["value"], e["expected"]["value"], "{call}: {a}");
            seen += 1;
        }
    }
    assert!(seen >= 9, "two examples of company_fact, one of annual_report and one of each method (one filing here): {seen}");
}
